from rules import is_acyclic, version_allowed


def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    names = sorted(packages)

    constraints = {name: [interval] for name, interval in roots.items()}
    required = set(roots)
    best = None
    best_vector = None

    def search(assigned, edges, needed, limits):
        nonlocal best, best_vector

        pending = sorted(needed - assigned.keys())
        if not pending:
            if not is_acyclic(assigned, edges):
                return
            result = {name: row['version'] for name, row in assigned.items()}
            vector = tuple(result.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best, best_vector = result, vector
            return

        name = pending[0]
        rows = packages.get(name, [])
        candidates = [row for row in rows
                      if version_allowed(row['version'], limits.get(name, []),
                                         blocked.get(name, []), pins.get(name))]
        candidates.sort(key=lambda row: row['version'], reverse=True)

        for row in candidates:
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_edges = {key: list(value) for key, value in edges.items()}
            next_edges[name] = []
            next_needed = set(needed)
            next_limits = {key: list(value) for key, value in limits.items()}
            valid = True

            for dep in row.get('deps', []):
                feature = dep.get('feature')
                if feature and feature not in features:
                    continue
                target = dep['name']
                interval = (dep['min'], dep['max'])
                next_needed.add(target)
                next_limits.setdefault(target, []).append(interval)
                next_edges[name].append(target)
                if target in next_assigned and not version_allowed(
                        next_assigned[target]['version'], next_limits[target],
                        blocked.get(target, []), pins.get(target)):
                    valid = False
                    break

            if valid and is_acyclic(next_assigned, next_edges, partial=True):
                search(next_assigned, next_edges, next_needed, next_limits)

    search({}, {}, required, constraints)
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best}

def version_allowed(version, intervals, blocked, pin):
    if pin is not None and version != pin:
        return False
    if version in blocked:
        return False
    return all(low <= version <= high for low, high in intervals)


def is_acyclic(assigned, edges, partial=False):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True
        state[name] = 1
        for target in edges.get(name, []):
            if target in assigned and not visit(target):
                return False
        state[name] = 2
        return True

    for name in assigned:
        if not visit(name):
            return False
    return True
